/* ExamRadar site — all data is read from site/data/*.json, nothing is hardcoded. */
(function () {
  "use strict";

  var COVERAGE_URL = "data/sample-coverage.json";
  var SESSIONS_URL = "data/qoder-sessions.json";
  var USAGE_URL = "data/usage-summary.json";
  var DEMO_VIDEO = "media/demo.mp4";

  var LEVEL_LABEL = { covered: "已覆盖", thin: "薄弱", missing: "缺失" };
  var QUESTION_SNIPPET = 60;

  function esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  function fmtNum(v, digits) {
    if (v == null || isNaN(v)) return "—";
    return Number(v).toFixed(digits == null ? 2 : digits);
  }

  function renderMarkdown(text) {
    if (typeof marked === "undefined") return "<p>" + esc(text) + "</p>";
    try {
      return marked.parse(esc(text));
    } catch (e) {
      return "<p>" + esc(text) + "</p>";
    }

"""Session 09d acceptance measurements: real screenshots + demo video, 1440x900 / 375x812."""

import json
import pathlib
import sys

from playwright.sync_api import sync_playwright

BASE = "http://127.0.0.1:18808"
SCRATCH = pathlib.Path(__file__).resolve().parent
ROOT = pathlib.Path(__file__).resolve().parent.parent.parent
SITE = ROOT / "site"

SHOTS = [
    "images/f1-import-ask.png",
    "images/f2-coverage-radar.png",
    "images/f3-review-coach.png",
    "images/f4-learner-memory.png",
    "images/f5-usage-log.png",
]

REPORT = {}
FAILED = []


def fail(msg):
    FAILED.append(msg)


def check_page(page, label, mobile=False):
    rep = {}

    # 1. all five screenshots really loaded, no placeholder box left behind
    rep["screenshots"] = page.evaluate(
        "() => Array.from(document.querySelectorAll('.screenshot img')).map(img => ({"
        "  src: img.getAttribute('src'),"
        "  complete: img.complete, naturalWidth: img.naturalWidth, naturalHeight: img.naturalHeight,"
        "  placeholder: !!img.closest('.screenshot').querySelector('.ph'),"
        "  visible: img.getBoundingClientRect().width > 0"
        "}))")
    by_src = {s["src"]: s for s in rep["screenshots"]}
    if len(by_src) != len(SHOTS):
        fail(f"{label}: found {len(by_src)} screenshot imgs, expected {len(SHOTS)}")
    for src in SHOTS:
        s = by_src.get(src)
        if not s:
            fail(f"{label}: missing img {src}")
            continue
        if not s["complete"] or s["naturalWidth"] <= 0:
            fail(f"{label}: {src} not loaded (naturalWidth={s['naturalWidth']})")
        if s["placeholder"]:
            fail(f"{label}: {src} still shows placeholder box")

    # screenshots must stay inside their .shot container (mobile included)
    overflow = page.evaluate(
        "() => Array.from(document.querySelectorAll('.feature .shot')).map(shot => {"
        "  const cr = shot.getBoundingClientRect();"
        "  const bad = [];"
        "  shot.querySelectorAll('.screenshot, .screenshot img, .shot-note').forEach(el => {"
        "    const r = el.getBoundingClientRect();"
        "    if (r.left < cr.left - 1 || r.right > cr.right + 1) bad.push({el: el.className || el.tagName, over: Math.round(r.right - cr.right)});"
        "  });"
        "  return {shot: Math.round(cr.width), bad, clipped: shot.scrollWidth > shot.clientWidth + 1};"
        "})")
    rep["shot_overflow"] = overflow
    for row in overflow:
        if row["bad"]:
            fail(f"{label}: element outside .shot container: {row['bad']}")
        if row["clipped"]:
            fail(f"{label}: .shot scrollWidth exceeds clientWidth ({row})")
    if mobile:
        sw = page.evaluate(
            "() => document.documentElement.scrollWidth - document.documentElement.clientWidth")
        rep["scroll_overflow"] = sw
        if sw > 0:
            fail(f"{label}: horizontal overflow {sw}px")

    # 2. demo video visible, placeholder hidden, duration 60-90s, poster loads
    rep["video"] = page.evaluate(
        """async () => {
          const v = document.getElementById('demo-video');
          const style = getComputedStyle(v);
          const pend = document.getElementById('video-pending');
          if (style.display === 'none') return {error: 'video hidden', display: style.display};
          const meta = await new Promise(res => {
            if (v.readyState >= 1) return res('already');
            const t = setTimeout(() => res('timeout'), 30000);
            v.addEventListener('loadedmetadata', () => { clearTimeout(t); res('event'); });
          });
          const poster = v.getAttribute('poster');
          const posterOk = await new Promise(res => {
            if (!poster) return res(0);
            const im = new Image();
            im.onload = () => res(im.naturalWidth);
            im.onerror = () => res(-1);
            im.src = poster;
          });
          return {display: style.display, visible: !!(v.offsetWidth || v.offsetHeight),
                  pending_hidden: pend.hidden || getComputedStyle(pend).display === 'none',
                  meta, duration: v.duration, readyState: v.readyState,
                  preload: v.getAttribute('preload'), poster, poster_naturalWidth: posterOk,
                  videoWidth: v.videoWidth, videoHeight: v.videoHeight};
        }""")
    v = rep["video"]
    if "error" in v:
        fail(f"{label}: {v['error']}")
    else:
        if not v["visible"]:
            fail(f"{label}: #demo-video not visible")
        if not v["pending_hidden"]:
            fail(f"{label}: #video-pending placeholder still visible")
        if v["preload"] != "metadata":
            fail(f"{label}: preload={v['preload']!r}, expected 'metadata'")
        if v["poster"] != "media/demo-poster.jpg":
            fail(f"{label}: poster={v['poster']!r}")
        if not isinstance(v["poster_naturalWidth"], int) or v["poster_naturalWidth"] <= 0:
            fail(f"{label}: poster image failed to load ({v['poster_naturalWidth']})")
        if v["meta"] == "timeout" or not (60 <= v["duration"] <= 90):
            fail(f"{label}: video.duration={v['duration']} (meta={v['meta']}), expected 60-90s")

    # 3. caption under the usage-log screenshot is visible
    rep["shot_note"] = page.evaluate(
        "() => {"
        "  const note = document.querySelector('.shot-note');"
        "  const shot = note ? note.closest('.shot') : null;"
        "  const sc = shot ? shot.querySelector('.screenshot') : null;"
        "  if (!note || !sc) return {error: 'not found'};"
        "  const nr = note.getBoundingClientRect(), sr = sc.getBoundingClientRect();"
        "  return {text: note.textContent.trim(), visible: !!(note.offsetWidth || note.offsetHeight),"
        "          height: Math.round(nr.height), below_screenshot: nr.top >= sr.bottom - 1};"
        "}")
    n = rep["shot_note"]
    if "error" in n:
        fail(f"{label}: .shot-note missing")
    else:
        if n["text"] != "截图里是开发测试数据，不是真实使用量。":
            fail(f"{label}: shot-note text mismatch: {n['text']!r}")
        if not n["visible"]:
            fail(f"{label}: shot-note not visible")
        if not n["below_screenshot"]:
            fail(f"{label}: shot-note is not below the screenshot")

    # 4. video section copy mentions duration / sample course / actual flow
    rep["video_sub"] = page.evaluate(
        "() => document.querySelector('#video .sec-sub').textContent")
    sub = rep["video_sub"]
    for needle in ("70 秒", "样例课程", "开发环境", "复习教练", "我的记忆", "使用记录", "问笔记", "覆盖雷达"):
        if needle not in sub:
            fail(f"{label}: video subtitle missing {needle!r}: {sub}")

    REPORT[label] = rep


def main() -> int:
    requests = []
    console_errors = []

    with sync_playwright() as p:
        browser = p.chromium.launch(channel="chrome", headless=True)

        for label, w, h, mobile in [("desktop_1440", 1440, 900, False), ("mobile_375", 375, 812, True)]:
            page = browser.new_page(viewport={"width": w, "height": h})
            page.on("request", lambda r: requests.append(r.url))
            page.on("console", lambda m: console_errors.append(m.text) if m.type == "error" else None)
            page.on("pageerror", lambda e: console_errors.append(str(e)))
            page.goto(BASE + "/", wait_until="networkidle")
            page.wait_for_timeout(2000)
            check_page(page, label, mobile)
            page.screenshot(path=str(SCRATCH / ("site-09d-desktop.png" if not mobile else "site-09d-mobile.png")),
                            full_page=True)
            page.close()

        # placeholder mechanism must still work when the video 404s (route-based)
        pg = browser.new_page(viewport={"width": 1440, "height": 900})
        pg.route("**/media/demo.mp4", lambda r: r.fulfill(status=404, body="not found"))
        pg.goto(BASE + "/", wait_until="networkidle")
        pg.wait_for_timeout(800)
        disp = pg.evaluate("() => getComputedStyle(document.getElementById('demo-video')).display")
        pend = pg.locator("#video-pending").is_visible()
        REPORT["video_404_routed"] = {"display": disp, "placeholder_visible": pend}
        if disp != "none" or not pend:
            fail(f"video 404 routed: display={disp}, placeholder={pend}")
        pg.close()

        browser.close()

    external = [u for u in requests if not u.startswith(BASE) and not u.startswith("data:")]
    REPORT["network"] = {"requests_total": len(requests), "external": external,
                         "console_errors": console_errors}
    if external:
        fail(f"external requests: {external}")
    if console_errors:
        fail(f"console errors (none expected now): {console_errors}")

    # site/ size excluding the video must stay under 3 MB
    video = (SITE / "media/demo.mp4").stat().st_size
    total = sum(f.stat().st_size for f in SITE.rglob("*") if f.is_file())
    REPORT["site_size_kb"] = {"total": round(total / 1024), "video": round(video / 1024),
                              "excl_video": round((total - video) / 1024)}
    if total - video >= 3 * 1024 * 1024:
        fail(f"site/ excl video {REPORT['site_size_kb']['excl_video']} KB >= 3MB")

    print(json.dumps(REPORT, ensure_ascii=False, indent=2, default=str))
    print("\n".join("FAILED: " + f for f in FAILED) if FAILED else "ALL 09d CHECKS PASSED")
    return 1 if FAILED else 0


if __name__ == "__main__":
    sys.exit(main())

